WITH with_windows AS (SELECT id, store_name, region, opened_date, LEAD(sqft, 1) OVER (PARTITION BY DATE_TRUNC('month', opened_date), region ORDER BY opened_date ASC, id ASC) AS next_sqft, SUM(sqft) OVER (PARTITION BY region ORDER BY sqft ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft FROM stores) SELECT id, store_name, region, running_sqft FROM with_windows ORDER BY region ASC NULLS LAST
